export type CountryLangType = {
    en: string;
    es: string;
    pt: string;
};
export type CountryData = {
    active: string;
    code: string;
    name: CountryLangType;
    b2cTenant: string;
    cluster: string;
    apiUrl: string;
    hubUrl: string;
    flag?: string;
};
export type CountryService = {
    data: Array<CountryData> | CountryData;
};
export type CountrySearchMethods = 'country' | 'cluster';
export type CountrySearch = {
    searchBy: CountrySearchMethods;
    id: string;
};
